function itsmRecs(c){const out={inc:[],chg:[],prb:[],req:[],via:{inc:[],chg:[],prb:[],req:[]}};try{const X=S.itsm||{};const svcs=new Set(impactSum(c.id).svcs.map(s=>s.id).concat(c.svc?[c.svc]:[]));const mine=ref=>ref&&(ref===c.id||String(ref).toLowerCase()===String(c.name).toLowerCase());const sv=x=>svId(x);
  (X.inc||[]).forEach(i=>{const r={id:i.id,t:i.t,sub:i.st,tag:i.id,st:/Resolved|Closed/.test(i.st||"")?"mute":"warn",go:()=>go("itsm_inc")};if(mine(i.ci))out.inc.push(r);else if(svcs.has(sv(i.svc)))out.via.inc.push(r)});
  (X.chg||[]).forEach(i=>{const r={id:i.id,t:i.t,sub:(i.type||"")+" · "+(i.st||""),tag:i.id,st:/Closed|Cancel/.test(i.st||"")?"mute":"info",go:()=>go("itsm_chg")};if((i.cis||[]).some(mine)||mine(i.ci))out.chg.push(r);else if(svcs.has(sv(i.svc)))out.via.chg.push(r)});
  (X.prb||[]).forEach(i=>{const r={id:i.id,t:i.t||i.title,sub:i.st,tag:i.id,st:/Closed|Resolved/.test(i.st||"")?"mute":"warn",go:()=>go("itsm_prb")};if(mine(i.ci))out.prb.push(r);else if(svcs.has(sv(i.svc||i.service)))out.via.prb.push(r)});
  (window.REQREG||[]).forEach(q=>{const r={id:q.id,t:q.item+" for "+(q.for||q.requester),sub:q.state,tag:q.id,st:/delivered|closed/i.test(q.state||"")?"mute":"info",go:()=>go("svc_req")};if(svcs.has(sv(q.service)))out.via.req.push(r)})}catch(e){}return out}
