function retireWhatIf(id){const c=ciOf(id);if(!c||c.isSvc)return;const w=whatIf(id);const rows=w.dep.slice(0,200).map(e=>{const d=ciOf(e[0]);return d?{id:d.id,t:d.name,sub:clsLabel(d.cls)+" · "+rtFw(e[2]),tag:w.lonely.includes(d)?"no alternative":"has alternative",st:w.lonely.includes(d)?"bad":"good",go:()=>ciDrawer(d.id)}:null}).filter(Boolean);
 openDrawer(`<div class="eyebrow">What-if: retire</div><h2 class="itom-h2">${esc(c.name)}</h2><div class="itom-note itom-v-${w.verdict[0]}" role="status"><b>${esc(w.verdict[1])}</b></div>
 <div class="statrow"><div class="stat"><small>Direct dependents</small><span class="num" data-role="metric">${w.dep.length}</span><em>would lose a dependency</em></div><div class="stat ${w.lonely.length?"crit":""}"><small>With no alternative</small><span class="num" data-role="metric">${w.lonely.length}</span><em>single points of failure</em></div><div class="stat"><small>Services affected</small><span class="num" data-role="metric">${w.imp.svcs.length}</span><em>${w.t1.length} are Tier 1</em></div><div class="stat"><small>Users</small><span class="num" data-role="metric">${fmt(w.imp.users)}</span><em>largest affected service</em></div></div>
 <h4>Dependents</h4>${lrHTML({id:"itom_wi_"+id,groups:[{key:"d",label:"Items that depend on "+c.name,rows}],limit:6,empty:"Nothing depends on this CI."})}
 <h4>Services above it</h4>${lrHTML({id:"itom_wis_"+id,groups:[{key:"s",label:"Services",rows:w.imp.svcs.map(s=>({id:s.id,t:s.n,sub:fmt(s.users)+" users",tag:s.tier,st:s.tier==="Tier 1"?"bad":"mute",go:()=>openSvc(s.id)}))}],limit:6,empty:"No service depends on it."})}
 <div class="row" style="margin-top:14px"><button class="btn danger" data-itom-a="retire" data-itom-v="${id}">${w.verdict[0]==="bad"?"Retire anyway (needs a reason)":"Retire now"}</button><button class="btn" data-itom-a="impact" data-itom-v="${id}">Full impact analysis</button><button class="btn quiet" data-itom-a="open" data-itom-v="${id}">Back to the CI</button></div>`);audit("what-if retire",c.name)}

/* ================= DATA MODEL SCREEN ================= */
const ciCnt=id=>{const h=HB.byCls||{};return h[id]||0};
const subCnt=id=>descOf(id).reduce((a,x)=>a+ciCnt(x),0);
function treeList(){const o=[];const walk=(id,d)=>{const c=CLM[id];if(!c)return;o.push({c,d});if(I.mdl.col[id])return;kidsOf(id).forEach(k=>walk(k.id,d+1))};walk("cmdb_ci",0);return o}
function mdlTree(){const sel=I.mdl.sel;return `<div class="itom-tree" role="tree" aria-label="Class hierarchy">${treeList().map(({c,d})=>{const k=kidsOf(c.id).length,n=subCnt(c.id),own=c.own.length,inh=attrsOf(c.id).length-own;return `<div class="itom-tr ${sel===c.id?"on":""}" style="--d:${d}" role="treeitem" aria-selected="${sel===c.id}"><button class="itom-tg" ${k?`data-itom-a="tog" data-itom-v="${c.id}" aria-label="${I.mdl.col[c.id]?"Expand":"Collapse"} ${esc(c.label)}"`:"disabled"}>${k?(I.mdl.col[c.id]?"▸":"▾"):"·"}</button><button class="itom-tn" data-itom-a="csel" data-itom-v="${c.id}"><i class="itom-dot" style="background:var(${DOM[c.dom].c})" title="CSDM domain: ${esc(DOM[c.dom].n)}"></i><b>${esc(c.label)}</b>${c.abs?`<span class="pill mute">abstract</span>`:""}${c.kind==="rec"?`<span class="pill mute">record</span>`:""}${c.cust?`<span class="pill info">custom</span>`:""}<small>${fmt(n)} CIs · ${own} own + ${inh} inherited</small></button></div>`}).join("")}</div>${legend(CSDM_DOMS.map(k=>[DOM[k].n,DOM[k].c]))}`}
function canRel(id){const o=[];EDGE_RT().forEach(r=>{const t=r.pairs.filter(p=>isA(id,p[0])).map(p=>p[1]);if(t.length)o.push([r,[...new Set(t)]])});return o}
function mdlDetail(){const c=CLM[I.mdl.sel]||CLM.cmdb_ci,at=attrsOf(c.id),lv=[];at.forEach(a=>{let g=lv.find(x=>x.id===a.lvlId);if(!g)lv.push(g={id:a.lvlId,l:a.lvl,a:[]});g.a.push(a)});
 const rules=RULES.filter(r=>isA(c.id,r.cls)),can=canRel(c.id);const own=c.own.length,req=at.filter(a=>a.req).length;
 const head=`<div class="itom-crumb">${chainOf(c.id).map(x=>`<button data-itom-a="csel" data-itom-v="${x.id}">${esc(x.label)}</button>`).join("<i>›</i>")}</div><div class="row sp"><h3 class="itom-h3">${esc(c.label)}</h3><span class="pill mute num">${esc(c.id)}</span></div><div class="row"><span class="pill" style="background:var(${DOM[c.dom].c});color:var(--accent-ink,#fff)">${esc(DOM[c.dom].n)}</span>${c.abs?`<span class="pill mute">Abstract: groups attributes, holds no CIs</span>`:`<span class="pill good">${fmt(ciCnt(c.id))} CIs of this exact class</span>`}${subCnt(c.id)!==ciCnt(c.id)?`<span class="pill info">${fmt(subCnt(c.id))} with subclasses</span>`:""}</div>
 <div class="row itom-act"><button class="btn primary" data-itom-a="newattr" data-itom-v="${c.id}">Add attribute</button><button class="btn" data-itom-a="newclass" data-itom-v="${c.id}">Add subclass</button><button class="btn" data-itom-a="newrule" data-itom-v="${c.id}">Add relationship rule</button>${c.abs?"":`<button class="btn" data-itom-a="listcls" data-itom-v="${c.id}">Show CIs</button>`}<button class="btn quiet" data-itom-a="editclass" data-itom-v="${c.id}">Edit class</button></div>
 <div class="statrow"><div class="stat"><small>Own attributes</small><span class="num">${own}</span><em>defined on this class</em></div><div class="stat"><small>Inherited</small><span class="num">${at.length-own}</span><em>from ${chainOf(c.id).length-1} parent classes</em></div><div class="stat"><small>Required</small><span class="num">${req}</span><em>counted double in completeness</em></div><div class="stat"><small>Subclasses</small><span class="num">${descOf(c.id).length-1}</span><em>inherit all of this</em></div></div>`;
 const attrs=lv.map((g,i)=>`<details ${i===lv.length-1||lv.length<4?"open":""}><summary>${i===lv.length-1?"Own: "+esc(g.l):"Inherited from "+esc(g.l)}<span class="cnt">${g.a.length}</span></summary>${tbl(["Attribute","Field name","Type","Rules","Choices or target"],g.a.map(a=>`<tr><td><b>${esc(a.label)}</b></td><td class="tok">${esc(a.k)}</td><td>${esc(a.t)}</td><td>${a.req?`<span class="pill bad">required</span>`:a.rec?`<span class="pill info">recommended</span>`:""}${a.idf?`<span class="pill mute">identifier</span>`:""}</td><td>${a.opts?esc(a.opts.join(", ")):a.ref?esc(clsLabel(a.ref)==a.ref?a.ref:clsLabel(a.ref)):""}${a.cust&&g.id===c.id?` <button class="itom-x" data-itom-a="delattr" data-itom-v="${c.id}|${a.k}" aria-label="Remove attribute ${esc(a.label)}">×</button>`:""}</td></tr>`),620)}</details>`).join("");
 const relz=`${can.length?tbl(["Relationship","Can point at"],can.map(([r,t])=>`<tr><td><b>${esc(r.fw)}</b><div class="muted small">${esc(r.rv)} from the other side</div></td><td>${t.map(x=>`<span class="pill mute">${esc(clsLabel(x))}</span>`).join(" ")}</td></tr>`),480):`<p class="muted">No relationship type is defined for this class yet.</p>`}${rules.length?`<h4>Required relationships</h4>${rules.map(r=>`<div class="itom-fi"><span><b>${esc(clsLabel(r.cls))}</b> ${esc(r.rel)} ${r.to.map(x=>esc(clsLabel(x))).join(" or ")}, at least ${r.min}<div class="muted small">${esc(r.why)}</div></span><span class="pill ${(HB.fails||{})[r.id]?"warn":"good"}">${(HB.fails||{})[r.id]||0} failing</span></div>`).join("")}`:""}`;
 return `<div class="itom-mdet">${head}<h4>Attributes by inheritance level</h4>${attrs}<h4>Relationships</h4>${relz}</div>`}
function mdlScreen(){ensure();const h=health();seedIng();const cls=CL.filter(c=>c.kind!=="rec"),ab=CL.filter(c=>c.abs).length,nat=CL.reduce((a,c)=>a+c.own.length,0),reqN=CL.reduce((a,c)=>a+c.own.filter(x=>x.req).length,0);const used=Object.keys(h.byCls).length;
 const story=`The CMDB data model has <b data-role="metric">${CL.length}</b> classes (${ab} abstract, ${CL.length-ab} concrete) and <b data-role="metric">${nat}</b> attributes, of which <b>${reqN}</b> are required. A Linux server inherits attributes from four parent classes. ${used} classes hold CIs today, and ${EDGE_RT().length} relationship types say how they connect. Add a class or an attribute here and every form, completeness score and field picker in Oukala learns it immediately.`;
 const extra=`<div class="row">${fchip("m_cmdb_comp")}${stdChip("csdm","Classes are placed in CSDM 5 domains; service classes follow the business service, offering, application service and technology management service pattern.")}<button class="btn primary" data-itom-a="newclass" data-itom-v="${I.mdl.sel}">New class</button><button class="btn" data-itom-a="newattr" data-itom-v="${I.mdl.sel}">New attribute</button>${whyPop("Every list, report builder and SLA definition picks real fields from this model, so a field you add here becomes usable everywhere.")}</div>`;
 const statrow=`<div class="statrow"><div class="stat"><small>Classes</small><span class="num" data-role="metric">${CL.length}</span><em>${used} hold CIs</em></div><div class="stat"><small>Attributes</small><span class="num" data-role="metric">${nat}</span><em>${reqN} required</em></div><div class="stat"><small>Relationship types</small><span class="num" data-role="metric">${RT.length}</span><em>${EDGE_RT().length} edge types, ${RT.length-EDGE_RT().length} attribute types</em></div><div class="stat"><small>Relationship rules</small><span class="num" data-role="metric">${RULES.length}</span><em>${RULES.filter(r=>!crOff[r.id]).length} active</em></div><div class="stat"><small>CSDM domains</small><span class="num" data-role="metric">${CSDM_DOMS.length}</span><em>${CSDM_DOMS.filter(k=>CL.some(c=>c.dom===k)).length} have classes</em></div><div class="stat"><small>Edges</small><span class="num" data-role="metric">${fmt(CIEDGE.length)}</span><em>relationships between records</em></div></div>`;
 const t1=`<div class="itom-mgrid"><div class="card glass"><div class="cardhead"><div><h3>Class hierarchy</h3><span class="muted small" data-role="story">Select a class to see what it inherits and what it adds. The dot shows its CSDM domain.</span></div></div>${mdlTree()}</div><div class="card glass">${mdlDetail()}</div></div>`;
 const edgeN={};CIEDGE.forEach(e=>edgeN[e[2]]=(edgeN[e[2]]||0)+1);const mxE=Math.max(1,...Object.values(edgeN));
 const t2=`${card("How relationships are used","Edges in this CMDB by type. Direction matters: a relationship always points from the item that depends to the item it depends on.",`<div class="itom-hb">${RT.map(r=>`<div class="itom-hr"><span><b>${esc(r.fw)}</b> <span class="muted small">/ ${esc(r.rv)}</span></span>${hbar(edgeN[r.k]||0,mxE,"--accent")}<b class="num" data-role="metric">${r.attr?"attribute":fmt(edgeN[r.k]||0)}</b></div>`).join("")}</div>`)}
 ${card("Relationship type catalog","Each type has a label for each direction, an example and the class pairs it is meant for. Types that read naturally the other way (Contains, Provides, Supports) are stored inverted so impact still flows upward.",tbl(["Type","Reads forward","Reads backward","Meaning and example","Allowed pairs"],RT.map(r=>`<tr><td><b>${esc(r.k)}</b>${r.flip?`<div class="muted small">entered inverted</div>`:""}${r.attr?`<div class="muted small">stored as ${esc(r.attr)}</div>`:""}</td><td>${esc(r.fw)}</td><td>${esc(r.rv)}</td><td>${esc(r.d)}<div class="muted small">Example: ${esc(r.ex)}</div></td><td>${r.pairs.slice(0,3).map(p=>`<span class="pill mute">${esc(clsLabel(p[0]))} → ${esc(clsLabel(p[1]))}</span>`).join(" ")}</td></tr>`),900),`<button class="btn primary" data-itom-a="newrt">New relationship type</button>`)}`;
 const t3=`<div class="itom-doms">${CSDM_DOMS.map(k=>{const d=DOM[k],cl=CL.filter(c=>c.dom===k),pop=cl.filter(c=>ciCnt(c.id)>0).length;return `<div class="itom-dom glass" style="--dc:var(${d.c})"><div class="row sp"><b>${esc(d.n)}</b><span class="pill mute">${pop} of ${cl.length} classes in use</span></div><p class="muted small">${esc(d.d)}</p><div class="muted small">CSDM 4 name: ${esc(d.was)}</div><div class="row">${cl.map(c=>`<button class="chip" data-itom-a="csel" data-itom-v="${c.id}">${esc(c.label)}${ciCnt(c.id)?` <b>${fmt(ciCnt(c.id))}</b>`:""}</button>`).join("")||`<span class="muted small">No classes here. This domain lives in other Oukala modules.</span>`}</div></div>`}).join("")}</div>${card("How the domains connect","A capability is supported by business applications; a business application has application services; application services run on technology management services and CIs; offerings expose them to the people who consume them.",`<div class="itom-flow" role="img" aria-label="CSDM flow from capability to business service">${["Business capability","Business application","Application service","Application and database CIs","Servers, VMs, network, storage","Rack and site"].map((x,i,a)=>`<span class="itom-fs">${esc(x)}</span>${i<a.length-1?`<i class="itom-fa" aria-hidden="true">→</i>`:""}`).join("")}</div><div class="itom-flow itom-flow2"><span class="itom-fs">Business service</span><i class="itom-fa">→</i><span class="itom-fs">Service offering</span><i class="itom-fa">→</i><span class="itom-fs">Application service</span><i class="itom-fa">→</i><span class="itom-fs">Technology management service</span><i class="itom-fa">→</i><span class="itom-fs">CIs</span></div>`,stdChip("csdm"))}`;
 const t4=card("Relationship rules (suggested relationships)","A CI of the class must have at least one relationship of this kind. Rules feed the compliance score; turn one off if it does not fit Meridian.",tbl(["Rule","Class","Needs","Failing now","Active"],RULES.map(r=>`<tr><td><b>${esc(r.id)}</b></td><td>${esc(clsLabel(r.cls))}</td><td>${esc(r.rel)} ${r.to.map(x=>esc(clsLabel(x))).join(" or ")}<div class="muted small">${esc(r.why)}</div></td><td class="num" data-role="metric">${(h.fails||{})[r.id]||0}</td><td><button class="chip" data-itom-a="rruleon" data-itom-v="${r.id}" aria-pressed="${!crOff[r.id]}">${crOff[r.id]?"Off":"On"}</button></td></tr>`),780),`<button class="btn primary" data-itom-a="newrule" data-itom-v="">Add rule</button>`);
 return `<div class="screen">${hero("CMDB · data model","Classes, attributes and relationships, like the CMDB it replaces",story,extra)}${lensNote()}${statrow}${views("itom_mdl",["Class hierarchy","Relationship types","CSDM 5 domains","Relationship rules"],[t1,t2,t3,t4])}${procCard("itom_model")}</div>`}
/* ---------- model forms ---------- */
const snake=s=>String(s||"").toLowerCase().replace(/[^a-z0-9]+/g,"_").replace(/^_|_$/g,"");
function classForm(parent,edit){const c=edit?CLM[edit]:null;OF({id:"itom_cls",title:c?"Edit class "+esc(c.label):"New class",story:c?"Renaming does not touch CIs. Moving a class between domains only changes how the CSDM map groups it.":"A class adds a kind of thing to the CMDB. It inherits every attribute of its parent, and CIs of the new class appear in lists, forms and the dependency view straight away. Custom classes get a u_ prefix so upgrades never collide with the standard model.",submit:c?"Save class":"Create class",
 fields:[{k:"label",label:"Class name",type:"text",req:true,ph:"for example Kubernetes cluster"},{k:"parent",label:"Parent class",type:"select",req:true,opts:CL.map(x=>[x.id,chainOf(x.id).map(y=>y.label).join(" › ")]),show:()=>!c,help:"The new class inherits all attributes from this parent."},{k:"dom",label:"CSDM domain",type:"select",req:true,opts:CSDM_DOMS.map(k=>[k,DOM[k].n])},{k:"abs",label:"Abstract",type:"toggle",help:"Abstract classes only group attributes and cannot hold CIs.",show:()=>!c},{k:"desc",label:"What belongs here",type:"longtext",ph:"One sentence for admins"}],
 defaults:c?{label:c.label,dom:c.dom,desc:c.desc||""}:{parent:parent||"cmdb_ci_cloud",dom:CLM[parent||"cmdb_ci_cloud"].dom,abs:false},
 liveH:v=>{if(c)return `<span class="muted">Table name <b>${esc(c.id)}</b></span>`;const p=CLM[v.parent];return `Table <b>u_${esc(snake(v.label)||"new_class")}</b> under <b>${esc(p?p.label:"")}</b>: inherits <b>${p?attrsOf(p.id).length:0}</b> attributes, of which ${p?attrsOf(p.id).filter(a=>a.req).length:0} are required.`},
 onSubmit:v=>{if(c){c.label=v.label;c.dom=v.dom;c.desc=v.desc;reindexCL();regModel();bump();audit("edited class",c.label);return{toast:"Class updated"}}const id="u_"+snake(v.label);if(!snake(v.label))return bad("Give the class a name.");if(CLM[id]||CL.some(x=>x.label.toLowerCase()===v.label.toLowerCase()))return bad("A class with that name already exists.");CL.push({id,label:v.label,parent:v.parent,abs:!!v.abs,dom:v.dom,own:[],cust:1,desc:v.desc});reindexCL();regModel();bump();I.mdl.sel=id;audit("created class",v.label+" under "+clsLabel(v.parent));render();return{toast:"Class "+v.label+" created. Add its attributes next."}}})}
const ATYPES=[["string","Text"],["int","Number"],["enum","Choice list"],["ref","Reference"],["bool","Yes or no"],["date","Date"],["ip","IP address"],["list","List"],["percent","Percent"],["money","Money"]];
function attrForm(cid){OF({id:"itom_attr",title:"Add an attribute",story:"An attribute is a field every CI of the class (and its subclasses) can carry. Required attributes count double in completeness, so adding one lowers the score until owners fill it in. That is the point: the model says what the Foundation needs to know.",submit:"Add attribute",
 fields:[{k:"cls",label:"Class",type:"select",req:true,opts:CL.map(x=>[x.id,chainOf(x.id).map(y=>y.label).join(" › ")])},{k:"label",label:"Label",type:"text",req:true,ph:"for example Patch window"},{k:"t",label:"Type",type:"chips",req:true,opts:ATYPES},{k:"opts",label:"Choices, one per line",type:"longtext",show:v=>v.t==="enum"},{k:"ref",label:"Reference points at",type:"select",opts:CL.map(x=>[x.id,x.label]),show:v=>v.t==="ref"},{k:"lvl",label:"How strict",type:"chips",opts:[["req","Required"],["rec","Recommended"],["opt","Optional"]]},{k:"idf",label:"Use as identifier",type:"toggle",help:"Identifiers are used by identification rules to recognize the same CI from different sources."}],
 defaults:{cls:cid||"cmdb_ci_server",t:"string",lvl:"opt"},
 liveH:v=>{const ids=v.cls?descOf(v.cls):[];const n=ids.reduce((a,x)=>a+ciCnt(x),0),h=HB;const add=v.lvl==="req"?2:v.lvl==="rec"?1:0;const after=h.wt?h.wf/(h.wt+add*n)*100:100;return `<b>${fmt(n)}</b> CIs carry this attribute. Key <span class="itom-c">${esc(snake(v.label)||"attribute")}</span>${add?`. Completeness would move from <b>${f1(h.comp)}%</b> to about <b>${f1(after)}%</b> until it is filled in.`:". Optional attributes do not change completeness."}`},
 onSubmit:v=>{const k=snake(v.label);if(!k)return bad("Give the attribute a label.");const cl=CLM[v.cls];if(attrsOf(v.cls).some(a=>a.k===k)||descOf(v.cls).some(x=>attrsOf(x).some(a=>a.k===k&&a.cust)))return bad("That field already exists on the class or a subclass.");const a={k,label:v.label,t:v.t,cust:1};if(v.lvl==="req")a.req=1;if(v.lvl==="rec")a.rec=1;if(v.idf)a.idf=1;if(v.t==="enum"){a.opts=String(v.opts||"").split("\n").map(x=>x.trim()).filter(Boolean);if(a.opts.length<2)return bad("Give at least two choices, one per line.")}if(v.t==="ref")a.ref=v.ref||"person";
  cl.own.push(a);ATC={};regModel();bump();health();audit("added attribute",cl.label+": "+v.label);I.mdl.sel=cl.id;render();return{toast:"Attribute added to "+cl.label+". Completeness recalculated."}}})}
function ruleForm(cid){OF({id:"itom_rrule",title:"Add a relationship rule",story:"A rule says what a healthy CI of this class is connected to. CIs that break the rule fail the compliance audit and show up in remediation tasks.",submit:"Add rule",
 fields:[{k:"cls",label:"When the CI is a",type:"select",req:true,opts:CL.filter(c=>!c.abs||true).map(c=>[c.id,chainOf(c.id).map(y=>y.label).join(" › ")])},{k:"rel",label:"It must have",type:"select",req:true,opts:EDGE_RT().map(r=>[r.k,r.fw])},{k:"to",label:"Pointing at (any of)",type:"multi",req:true,opts:CL.filter(c=>c.kind!=="rec").map(c=>[c.id,c.label]).slice(0,30)},{k:"why",label:"Why",type:"text",req:true,ph:"One plain sentence the support team will see"}],defaults:{cls:cid||"cmdb_ci_appl",rel:"runs on",to:[]},
 liveH:v=>{if(!v.cls||!(v.to||[]).length)return `<span class="muted">Choose a class and at least one target class.</span>`;const r={id:"x",cls:v.cls,rel:v.rel,to:v.to,min:1};const n=CIREG.filter(c=>c.life!=="Retired"&&isA(c.cls,v.cls)&&!c.isSvc&&!c.svcLayer);let f=0;n.forEach(c=>{if(relFail(r,c))f++});return `<b>${fmt(f)}</b> of ${fmt(n.length)} existing ${esc(clsLabel(v.cls))} CIs would fail this rule today.`},
 onSubmit:v=>{const id="RR"+(++I.seq);RULES.push({id,cls:v.cls,rel:v.rel,to:v.to,min:1,why:v.why,on:1});bump();health();audit("added relationship rule",clsLabel(v.cls)+" "+v.rel);render();return{toast:"Rule "+id+" added. Compliance recalculated."}}})}
