function finScreen(){const sb=showback(),W=wasteNow(),tot=105,wp=Math.round(W/tot*1000)/10;METRICS.m_cloud_waste.cur=wp;const un=untagged(),cov=(1-un/tot)*100,real=RECS.filter(r=>I.fin.accepted[r[0]]).reduce((a,r)=>a+r[4],0);
 const mu=DAILY.slice(0,25).reduce((a,b)=>a+b,0)/25,sd=Math.sqrt(DAILY.slice(0,25).reduce((a,b)=>a+(b-mu)**2,0)/25);const hi=DAILY.map(()=>mu+2*sd),lo=DAILY.map(()=>mu-2*sd),pts=DAILY.map((v,i)=>v>mu+2*sd?{i,v,color:col("--bad-f"),t:"Anomaly: $"+v.toFixed(2)+"K"}:null).filter(Boolean);
 const dim=I.dims,rows=dim==="Service"?SVCS:dim==="Department"?DEPT.map(d=>[d[0],d[1]]).concat([["Untagged",un]]):[["Production",71.2],["Test",12.4],["Development",6.6],["Untagged",un]];
 const spend=card("Where the money goes","September actual by "+dim.toLowerCase()+", $"+tot.toFixed(1)+"K total",`<div class="row">${["Service","Department","Environment"].map(d=>`<button class="chip" data-itom-findim="${d}" aria-pressed="${dim===d}">${d}</button>`).join("")}</div><div class="itom-hb">${rows.map(r=>`<div class="itom-hr"><span>${r[0]}</span><div class="itom-ht"><i style="width:${Math.max(2,r[1]/Math.max(...rows.map(x=>x[1]))*100)}%;${r[0]==="Untagged"?"background:var(--warn-f)":""}"></i></div><b class="num" data-role="metric">${K1(r[1]*1000)}</b></div>`).join("")}</div>`);
 const budget=card("Budget against actual","Monthly Azure consumption, billed through the Northwind Cloud MSA (budget line B1, $1.2M a year)",bars({labels:MON,vals:ACT.concat([FC]),fc:[9],max:120,line:BUD,lineLabel:"Budget $100K",fmt:v=>"$"+Math.round(v)+"K",alt:"Monthly cloud spend against budget"})+`<div class="formula">Budget burn = Month actual ÷ Monthly budget = $105K ÷ $100K = 105%. October forecast $112K is 112%: ${K1(112000-100000)} over unless the SQL scale-up is reverted.</div>`,fchip("m_budgetburn"));
 const anom=card("Anomaly detection","Daily cost for 30 days. The band is the mean plus or minus 2 standard deviations of the first 25 days ($"+mu.toFixed(2)+"K ± $"+(2*sd).toFixed(2)+"K).",chart({labels:DAILY.map((_,i)=>i%5===0?"-"+(30-i)+"d":i===29?"today":""),max:6,min:0,fmt:v=>"$"+v.toFixed(0)+"K",ticks:3,band:{hi,lo},series:[{vals:DAILY,color:col("--accent"),nodot:true}],pts,alt:"Daily cloud cost with anomaly band"})+`<div class="itom-an"><b>${pts.length} anomalous days</b><span data-role="story">SQL managed instance was scaled from General Purpose 8 vCore to Business Critical 16 vCore on Oct 5 at 14:20 during INC1. It adds $1,870 a day, about $56K a month if left.</span><div class="row">${aiChip({model:"FinOps Agent",conf:.92,title:"Anomaly cause",src:["Azure Cost Management daily export","Resource activity log: scale operation by Sam Patel","INC1 timeline"],guards:["Read only"]})}<button class="btn primary" data-itom-revert ${I.fin.reverted?"disabled":""}>${I.fin.reverted?"Revert scheduled":"Schedule revert after INC1"}</button></div></div>`);
 const tagc=card("Untagged spend","Resources missing a required team or costcenter tag. Tag coverage = 1 − Untagged ÷ Total spend = "+cov.toFixed(1)+"%.",tbl(["Service","Untagged","Resources","Likely owner"],UNT.map(u=>`<tr style="cursor:default"><td><b>${u[0]}</b></td><td data-role="metric">${K1(u[1]*(I.fin.tagFixed?.38:1)*1000)}</td><td>${Math.max(1,Math.round(u[2]*(I.fin.tagFixed?.38:1)))}</td><td>${u[0].includes("SQL")?"Data team":u[0]==="Virtual machines"?"Finance systems":u[0]==="App Service"?"Platform team":"Shared"}</td></tr>`),460)+`<div class="itom-an"><span data-role="story">${I.fin.tagFixed?"Tag inheritance is on: 62% of the untagged resources now take their resource group's tags.":"Most untagged resources sit in resource groups that are tagged. Azure Policy can copy the tag down."}</span><div class="row"><button class="btn primary" data-itom-tagfix ${I.fin.tagFixed?"disabled":""}>${I.fin.tagFixed?"Policy applied":"Apply tag inheritance policy"}</button>${aiChip({model:"FinOps Agent",conf:.87,title:"Tag inheritance impact",src:["Resource group tags","Azure Policy: Inherit a tag from the resource group"],guards:["Policy modifies tags only, never resources"]})}</div></div>`);
 const show=card("Showback by department","Direct tagged cost, tag-fix recovery and shared allocation. Variance is against each department's share of the $100K budget.",tbl(["Department","Direct","Recovered by tag fix","Shared allocation","Total","Budget","Variance"],sb.rows.map(r=>`<tr style="cursor:default"><td><b>${r.n}</b></td><td>${K1(r.dir*1000)}</td><td>${K1(r.fix*1000)}</td><td>${K1(r.alloc*1000)}</td><td data-role="metric"><b>${K1(r.tot*1000)}</b></td><td>${K1(r.bud*1000)}</td><td><span class="pill ${r.tot>r.bud?"warn":"good"}">${r.tot>r.bud?"+":""}${((r.tot-r.bud)).toFixed(1)}K</span></td></tr>`).concat([`<tr style="cursor:default"><td><b>Unallocated</b></td><td colspan="3" class="muted">Cost no rule or tag can place yet</td><td data-role="metric"><b>${K1(sb.unalloc*1000)}</b></td><td>$17.0K shared pool</td><td></td></tr>`]),760),`<button class="btn primary" data-itom-newalloc>Add allocation rule</button>`);
 const rec=card("Rightsizing recommendations","AI proposals from 30 days of utilization. Accepting queues a change; nothing resizes without the change approval.",`<div class="itom-recs">${RECS.map(r=>`<div class="itom-rec ${I.fin.accepted[r[0]]?"acc":""}"><div><b>${r[1]}</b> <span class="pill ${r[5]==="Low"?"good":"warn"}">${r[5]} risk</span><div>${r[2]}</div><div class="muted small">${r[3]}</div></div><div class="row"><b class="num" data-role="metric">${K1(r[4]*1000)}/mo</b>${aiChip({model:"FinOps Agent",conf:r[6],title:"Why "+r[1],src:["Azure Advisor","Azure Monitor utilization (30 days)","Pricing sheet"],guards:["Needs change approval","Reversible"]})}<button class="btn ${I.fin.accepted[r[0]]?"":"primary"}" data-itom-acc="${r[0]}" ${I.fin.accepted[r[0]]?"disabled":""}>${I.fin.accepted[r[0]]?"Accepted":"Accept"}</button></div></div>`).join("")}</div><div class="formula">Waste share = Remaining recommended savings ÷ Monthly spend = ${K1(W*1000)} ÷ $105.0K = ${wp}%. Realized so far: ${K1(real*1000)} a month.</div><div class="row">${fchip("m_cloud_waste")}<span class="muted small">Target 8% or less.</span></div>`);
 return `<div class="screen">${hero("Cloud cost (FinOps)","Know who spends what, and stop paying for idle",`September Azure spend was <b data-role="metric">$105K</b> against a $100K budget (105%), and October is forecast at $112K because the SQL instance was scaled up during the portal incident. <b>${wp}%</b> of spend is recoverable waste.`,`<div class="row">${fchip("m_budgetburn")}${fchip("m_cloud_waste")}<button class="btn" data-itom-newalloc>Add allocation rule</button>${whyPop("Finance and IT Ops share this screen: it connects spend to the budget line and to the team that owns it.")}</div>`)}${lensNote()}${finStats(wp,cov,pts.length,real)}${views("itom_fin",["Spend and budget","Untagged and showback","Rightsizing"],[`<div class="grid g2" style="align-items:start">${budget}${anom}</div>${spend}`,`<div class="grid g2" style="align-items:start">${tagc}${show}</div>`,rec])}${finScale()}${procCard("itom_fin")}</div>`}
function allocForm(){OF({id:"itom_alloc",title:"Cost allocation rule",story:"A rule places untagged cost on a department so showback is complete before tags are fixed. It never changes the bill, only who sees it.",submit:"Save rule",
 fields:[{k:"n",label:"Rule name",type:"text",req:true,ph:"e.g. Shared SQL cost"},{k:"svc",label:"Applies to untagged spend in",type:"select",req:true,opts:UNT.filter(u=>!I.fin.rules.some(r=>r.svc===u[0])).map(u=>u[0])},{k:"dept",label:"Allocate to",type:"chips",opts:["Publishing","IT Platform","Finance","Legal","Split by usage"],req:true},{k:"pr",label:"Priority",type:"number",min:1,help:"Lower numbers run first."}],defaults:{dept:"Split by usage",pr:2},
 liveH:v=>{const u=UNT.find(x=>x[0]===v.svc);if(!u)return "Every untagged service already has a rule.";const a=u[1]*(I.fin.tagFixed?.38:1);return `<b>Effect:</b> ${K1(a*1000)} a month moves from Unallocated to ${v.dept==="Split by usage"?"all departments in proportion to direct spend":v.dept||"the chosen department"}. Unallocated would drop from ${K1(showback().unalloc*1000)} to ${K1(Math.max(0,showback().unalloc-a)*1000)}.`},
 onSubmit:v=>{if(!UNT.find(x=>x[0]===v.svc))return bad("All untagged services already have a rule.");I.fin.rules.push({id:nextId("CA"),n:v.n,svc:v.svc,dept:v.dept,pr:+v.pr||2});render();return {toast:"Rule saved: "+v.n,audit:"added cost allocation rule "+v.n}}})}


