function autoMap(){const s=SRCM[I.ing.src],st=I.srcs[s.id];const tg=mapTargets(s);let n=0;s.fields.filter(f=>!st.map.some(m=>m.f===f)).forEach(f=>{const h=MAPHINT.find(x=>x[0].test(f));if(!h)return;const t=tg.find(x=>x.k===h[1]);if(!t||st.map.some(m=>m.a===t.k))return;st.map.push({f,a:t.k,x:"as is"});n++});audit("auto-mapped fields",s.s+": "+n+" suggestions accepted");toast(n?"Mapped "+n+" more fields. Check the preview.":"No further matches found","info");render()}
function saveViewForm(){OF({id:"itom_sv",title:"Save this view",story:"A saved view remembers the quick view and every facet and search term in the CI list. It is private to you; share it from the team views screen when it is useful to others.",submit:"Save view",fields:[{k:"n",label:"Name",type:"text",req:true,ph:"for example Production, no owner"}],
 onSubmit:v=>{const b=S.bt.itom_ci||{};const id="SV"+(++I.seq);I.saved.push({id,n:v.n,view:I.view,f:JSON.parse(JSON.stringify(b.f||{})),q:b.q||""});I.curSaved=id;audit("saved CI view",v.n);render();return{toast:"Saved view "+v.n}}})}
