function ensureTask(rule){seedTasks();let t=I.tasks.find(x=>x.rule===rule);if(t){if(t.st==="Done")t.st="Open";return t}health();const H=HB;let list=[],ttl="",grp="Ops team";if(/^(CR|RR)/.test(rule)){list=H.act.filter(c=>c._h.fails.includes(rule));const r=compRules().find(x=>x.id===rule);ttl="Fix "+list.length+" CIs failing: "+(r?r.n:rule)}else{list=rule==="stale"?H.stale:rule==="orphan"?H.orph:H.dupPairs.map(p=>p.b);ttl="Resolve "+list.length+" "+rule+" CIs"}
 t={id:"RT-"+(101+I.tasks.length),t:ttl,rule,n:list.length,ci:list.slice(0,300).map(c=>c.id),grp,due:"Oct 30",st:"Open",dem:false};I.tasks.push(t);return t}
function taskCIs(id){const t=I.tasks.find(x=>x.id===id);if(!t)return;const rows=t.ci.map(ciOf).filter(Boolean).slice(0,300).map(c=>({id:c.id,t:c.name,sub:clsLabel(c.cls)+" · "+(c.grp||"no group"),tag:c.env,st:stCls(c.status),go:()=>ciDrawer(c.id)}));openDrawer(`<div class="eyebrow">Remediation task ${esc(t.id)}</div><h2 class="itom-h2">${esc(t.t)}</h2><p class="muted">${esc(t.grp)} · due ${esc(t.due)} · ${fmt(t.n)} CIs${t.n>rows.length?", first "+rows.length+" shown":""}</p>${lrHTML({id:"itom_tc_"+id,groups:[{key:"c",label:"CIs in this task",rows}],limit:8,empty:"Nothing left to fix."})}`)}
