DND.on("itommap",(id,from,to)=>{const st=I.srcs[I.ing.src];if(!to||to===from)return render();if(to==="pool")st.map=st.map.filter(m=>m.f!==id);else if(/^slot:/.test(to)){const a=to.slice(5);st.map=st.map.filter(m=>m.f!==id&&m.a!==a);st.map.push({f:id,a,x:"as is"})}else return render();audit("mapped field",SRCM[I.ing.src].s+": "+id+" to "+to);toast(to==="pool"?id+" unmapped":id+" now fills "+to.slice(5),"good");render()});
